namespace Encspect.Formats.Dts.Decoding;

// The two vector tables of Annex D.10, from VectorData (generated by dts_tables.py: the specification names them and does not print them): D.10.1, the 4,096 vectors of four ADPCM
// prediction coefficients, each element a multiple of 2^-13, and D.10.2, the 1,024 vectors of 32 samples of the high-frequency subbands, each a multiple of 2^-4.
internal static class VectorTables
{
    public static void Coefficients(int index, Span<float> destination)
    {
        ReadOnlySpan<short> row = VectorData.Adpcm.Slice((index & 0xFFF) * 4, 4);
        for (int k = 0; k < 4; k++)
        {
            destination[k] = row[k] / 8192f;
        }
    }

    public static void HighFrequency(int index, Span<float> destination)
    {
        ReadOnlySpan<sbyte> row = VectorData.HighFrequency.Slice((index & 0x3FF) * 32, 32);
        for (int m = 0; m < 32; m++)
        {
            destination[m] = row[m] / 16f;
        }
    }
}
